  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Validate all nodes have core_distance
    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Missing core_distance for node {node}")

    # Build edges with mutual reachability distance
    edges = []
    seen = set()
    for u, v, d in distances:
        if u not in core_distance or v not in core_distance:
            raise ValueError(f"Unknown node in distance pair ({u},{v})")
        if u == v:
            continue
        if u > v:
            u, v = v, u
        key = (u, v)
        if key in seen:
            continue  # ignore duplicate
        seen.add(key)
        mrd = max(core_distance[u], core_distance[v], d)
        edges.append((mrd, u, v))

    # Sort deterministically: weight, then u, then v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find with path compression and union by rank
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n_nodes = len(nodes)
    n_edges_needed = n_nodes - 1

    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == n_edges_needed:
                break

    if len(mst_edges) != n_edges_needed:
        raise ValueError("Graph is disconnected; cannot form a spanning tree.")

    # Sort output edges deterministically
    mst_edges.sort(key=lambda e: (e[2], e[0], e[1]))

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
